#### 2441\. 与对应负数同时存在的最大正整数
(https://leetcode.cn/problems/largest-positive-integer-that-exists-with-its-negative/) ![[#^8xhsf5]] 双指针法：
```cpp
class Solution {
public:
    int findMaxK(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int left = 0,right = nums.size()-1;
        while(left<right){
            if(nums[left]>0||nums[right]<0)
                return -1;
            if(nums[left]+nums[right]>0){
                right--;
            }else if(nums[left]+nums[right]<0){
                left++;
            }else{
                return nums[right];
            }
        }
        return -1;
    }
};
```
-   两数之和，a+b=c，由数学规律可知 `a<c/2 && b>c/2` 刚好符合指针**从两边向中间靠拢**形式，可以使用双指针对**排序过后的数组**遍历 两数之和思路：
```cpp
class Solution {
public:
    int findMaxK(vector<int>& nums) {
        unordered_set<int> mapping;
        int temp = INT_MIN;
        for(int k : nums){
            if(mapping.find(k)!=mapping.end()){
                temp = max(temp, k > 0 ? k : -k);
            }else{
                mapping.insert(-k);
            }
        }
        return temp == INT_MIN ? -1 : temp;
    }
};
```

